class BadRecurse {
    fun recurse(n: Int) {
        recurse(n) // bad
    }
}

class BadExpressionRecurse {
    fun recurse(n: Int): Int = recurse(n) // bad
}

class GoodRecurse {
    fun recurse(n: Int): Int = if (n <= 0) 0 else recurse(n - 1)
}

class GoodFactorial {
    tailrec fun factorial(n: Int, acc: Int = 1): Int =
        if (n <= 1) acc else factorial(n - 1, acc * n)
}
